-- ============================================================
-- CMS 数据库初始化脚本（重置型，可重复执行）
-- 执行内容：1) 删除同名表（含历史 PascalCase 表名，避免新旧表并存）
--           2) 重建表结构  3) 写入初始数据
-- 警告：会清空同名表的现有数据，请勿在生产库直接执行；
--       如需在保留数据的前提下改表名，请改用 npm run db:migrate
-- ============================================================
SET FOREIGN_KEY_CHECKS = 0;
SET NAMES utf8mb4;
-- 重建前清理（新表名 + 历史表名）
DROP TABLE IF EXISTS
  `sys_button_auth`, `sys_dict`, `sys_login_log`, `sys_operation_log`,
  `sys_role`, `sys_role_button`, `sys_role_route`, `sys_route_auth`, `sys_user`, `sys_user_role`, `tag`,
  `ButtonAuth`, `Dict`, `LoginLog`, `OperationLog`,
  `RoleButton`, `RoleRoute`, `Roles`, `RouteAuth`, `Tag`, `UserRole`, `Users`;
-- sys_button_auth DDL
CREATE TABLE `sys_button_auth` (`button_id` INT NOT NULL AUTO_INCREMENT,
`route_id` INT NOT NULL Comment '所属菜单ID',
`route_name` VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL Comment '所属路由名称，冗余字段便于展示和查询',
`button_name` VARCHAR(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL Comment '按钮权限编码，如 user:add',
`button_label` VARCHAR(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL Comment '按钮显示名称，如 新增/编辑/删除',
`order_num` INT NOT NULL DEFAULT 0 Comment '排序号',
`status` TINYINT NOT NULL DEFAULT 1 Comment '状态：1=启用 0=禁用',
`create_by` VARCHAR(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' Comment '创建人',
`create_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP Comment '创建时间',
`update_by` VARCHAR(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' Comment '更新人',
`update_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP(0) Comment '更新时间',
INDEX `idx_button_route_name`(`route_name` ASC) USING BTREE,
UNIQUE INDEX `uk_route_button_name`(`route_id` ASC,`button_name` ASC) USING BTREE,
PRIMARY KEY (`button_id`)) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci AUTO_INCREMENT = 16 ROW_FORMAT = Dynamic COMMENT = '按钮权限表';
-- sys_dict DDL
CREATE TABLE `sys_dict` (`id` INT NOT NULL AUTO_INCREMENT,
`dict_name` VARCHAR(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL Comment '字典名称',
`dict_code` VARCHAR(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL Comment '字典编码',
`status` TINYINT NOT NULL DEFAULT 1 Comment '状态：1=启用 0=禁用',
`remark` VARCHAR(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' Comment '备注',
`create_by` VARCHAR(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' Comment '创建人',
`create_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP Comment '创建时间',
`update_by` VARCHAR(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' Comment '更新人',
`update_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP(0) Comment '更新时间',
UNIQUE INDEX `uk_dict_code`(`dict_code` ASC) USING BTREE,
UNIQUE INDEX `uk_dict_name`(`dict_name` ASC) USING BTREE,
PRIMARY KEY (`id`)) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci AUTO_INCREMENT = 2 ROW_FORMAT = Dynamic COMMENT = '字典管理表';
-- sys_login_log DDL
CREATE TABLE `sys_login_log` (`id` INT NOT NULL AUTO_INCREMENT,
`user_id` INT NULL Comment '用户ID',
`username` VARCHAR(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL Comment '用户名',
`login_type` VARCHAR(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL Comment '登录类型：password/code/sms',
`ip_address` VARCHAR(45) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL Comment 'IP地址',
`location` VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL Comment '登录地点',
`browser` VARCHAR(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL Comment '浏览器',
`os` VARCHAR(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL Comment '操作系统',
`user_agent` VARCHAR(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL Comment '完整UA',
`status` TINYINT NOT NULL DEFAULT 1 Comment '登录状态：1=成功 0=失败',
`message` VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL Comment '登录消息',
`session_id` VARCHAR(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL Comment '会话ID',
`create_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP Comment '登录时间',
INDEX `idx_create_time`(`create_time` ASC) USING BTREE,
INDEX `idx_ip_address`(`ip_address` ASC) USING BTREE,
INDEX `idx_status`(`status` ASC) USING BTREE,
INDEX `idx_user_id`(`user_id` ASC) USING BTREE,
INDEX `idx_username`(`username` ASC) USING BTREE,
PRIMARY KEY (`id`)) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci AUTO_INCREMENT = 17 ROW_FORMAT = Dynamic COMMENT = '登录日志表';
-- sys_operation_log DDL
CREATE TABLE `sys_operation_log` (`id` INT NOT NULL AUTO_INCREMENT,
`user_id` INT NULL Comment '操作用户ID',
`username` VARCHAR(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL Comment '操作用户名',
`action` VARCHAR(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL Comment '操作类型',
`module` VARCHAR(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL Comment '系统模块',
`method` VARCHAR(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL Comment '请求方法 GET/POST/PUT/DELETE',
`request_url` VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL Comment '请求URL',
`request_params` TEXT CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL Comment '请求参数(JSON)',
`response_status` VARCHAR(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL Comment '响应状态码',
`response_msg` VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL Comment '响应消息',
`response_body` TEXT CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL Comment '响应体(JSON)',
`ip_address` VARCHAR(45) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL Comment 'IP地址',
`user_agent` VARCHAR(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL Comment '浏览器标识',
`execute_time` INT NULL Comment '执行时间(毫秒)',
`status` TINYINT NOT NULL DEFAULT 1 Comment '操作状态：1=成功 0=失败',
`create_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP Comment '操作时间',
INDEX `idx_action`(`action` ASC) USING BTREE,
INDEX `idx_create_time`(`create_time` ASC) USING BTREE,
INDEX `idx_module`(`module` ASC) USING BTREE,
INDEX `idx_status`(`status` ASC) USING BTREE,
INDEX `idx_user_id`(`user_id` ASC) USING BTREE,
INDEX `idx_username`(`username` ASC) USING BTREE,
PRIMARY KEY (`id`)) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci AUTO_INCREMENT = 38 ROW_FORMAT = Dynamic COMMENT = '操作日志表';
-- sys_role_button DDL
CREATE TABLE `sys_role_button` (`role_button_id` INT NOT NULL AUTO_INCREMENT,
`role_id` INT NOT NULL Comment '角色ID',
`button_id` INT NOT NULL Comment '按钮ID',
`create_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP Comment '创建时间',
INDEX `idx_role_button_button_id`(`button_id` ASC) USING BTREE,
UNIQUE INDEX `uk_role_button`(`role_id` ASC,`button_id` ASC) USING BTREE,
