-- sys_role_route DDL
CREATE TABLE `sys_role_route` (`role_route_id` INT NOT NULL AUTO_INCREMENT,
`role_id` INT NOT NULL Comment '角色ID',
`route_id` INT NOT NULL Comment '菜单ID',
`create_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP Comment '创建时间',
INDEX `idx_role_route_route_id`(`route_id` ASC) USING BTREE,
UNIQUE INDEX `uk_role_route`(`role_id` ASC,`route_id` ASC) USING BTREE,
PRIMARY KEY (`role_route_id`)) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci AUTO_INCREMENT = 130 ROW_FORMAT = Dynamic COMMENT = '角色菜单权限关联表';
-- sys_role DDL
CREATE TABLE `sys_role` (`role_id` INT NOT NULL AUTO_INCREMENT,
`role_code` VARCHAR(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL Comment '角色编码，程序内唯一标识',
`role_name` VARCHAR(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL Comment '角色名称',
`description` VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL Comment '角色描述',
`status` TINYINT NOT NULL DEFAULT 1 Comment '状态：1=启用 0=禁用',
`is_system` TINYINT(1) NOT NULL DEFAULT 0 Comment '是否系统内置角色：1=是 0=否',
`create_by` VARCHAR(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' Comment '创建人',
`create_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP Comment '创建时间',
`update_by` VARCHAR(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' Comment '更新人',
`update_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP(0) Comment '更新时间',
UNIQUE INDEX `uk_role_code`(`role_code` ASC) USING BTREE,
UNIQUE INDEX `uk_role_name`(`role_name` ASC) USING BTREE,
PRIMARY KEY (`role_id`)) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci AUTO_INCREMENT = 3 ROW_FORMAT = Dynamic COMMENT = '角色表';
-- sys_route_auth DDL
CREATE TABLE `sys_route_auth` (`id` INT NOT NULL AUTO_INCREMENT,
`parent_id` INT NULL Comment '父级菜单ID，NULL表示顶级菜单',
`menu_type` TINYINT NOT NULL DEFAULT 2 Comment '菜单类型：1=目录 2=菜单页面',
`menu_name` VARCHAR(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL Comment '菜单名称（显示标题）',
`route_name` VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL Comment '路由名称（唯一标识）',
`route_path` VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL Comment '路由路径',
`component` VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL Comment '前端组件路径',
`redirect` VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL Comment '重定向路径',
`order_num` INT NOT NULL DEFAULT 0 Comment '排序序号',
`icon` VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL Comment '菜单图标',
`icon_type` TINYINT NOT NULL DEFAULT 1 Comment '图标类型：1=iconify',
`i18n_key` VARCHAR(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL Comment '国际化key',
`hide_in_menu` TINYINT(1) NOT NULL DEFAULT 0 Comment '是否在菜单中隐藏：0=否 1=是',
`active_menu` VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL Comment '激活菜单路由名',
`multi_tab` TINYINT(1) NOT NULL DEFAULT 0 Comment '是否支持多标签页：0=否 1=是',
`keep_alive` TINYINT(1) NOT NULL DEFAULT 0 Comment '是否缓存：0=否 1=是',
`status` TINYINT NOT NULL DEFAULT 1 Comment '状态：1=启用 0=禁用',
`create_by` VARCHAR(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' Comment '创建人',
`create_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP Comment '创建时间',
`update_by` VARCHAR(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' Comment '更新人',
`update_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP(0) Comment '更新时间',
INDEX `idx_route_parent_id`(`parent_id` ASC) USING BTREE,
INDEX `idx_route_status`(`status` ASC) USING BTREE,
UNIQUE INDEX `uk_route_name`(`route_name` ASC) USING BTREE,
UNIQUE INDEX `uk_route_path`(`route_path` ASC) USING BTREE,
PRIMARY KEY (`id`)) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci AUTO_INCREMENT = 44 ROW_FORMAT = Dynamic COMMENT = '菜单路由权限表';
-- tag DDL
CREATE TABLE `tag` (`id` VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
