-- sys_user DDL
CREATE TABLE `sys_user` (`id` INT NOT NULL AUTO_INCREMENT,
`username` VARCHAR(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL Comment '用户名',
`nick_name` VARCHAR(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL Comment '昵称',
`gender` ENUM("male","female","other") CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'other' Comment '性别',
`status` TINYINT NOT NULL DEFAULT 1 Comment '状态：1=启动 0=禁用；接口层可转为字符串',
