`phone` VARCHAR(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL Comment '手机号',
`id_card` VARCHAR(18) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL Comment '身份证号',
`email` VARCHAR(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL Comment '邮箱',
`address` VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL Comment '地址',
`avatar` VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL Comment '头像地址',
`password` VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL Comment '登录密码（加密后）',
`current_refresh_token` VARCHAR(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL Comment '当前有效的 Refresh Token（用于单设备登录控制）',
`session_id` VARCHAR(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL Comment '当前会话 ID（UUID，用于单设备登录控制）',
`login_ip` VARCHAR(45) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL Comment '登录 IP 地址',
`login_time` DATETIME NULL Comment '登录时间',
`session_expire` DATETIME NULL Comment '会话过期时间',
`create_by` VARCHAR(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' Comment '创建人',
`create_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP Comment '创建时间',
`update_by` VARCHAR(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' Comment '更新人',
`update_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP(0) Comment '更新时间',
INDEX `idx_user_create_time`(`create_time` ASC) USING BTREE,
INDEX `idx_user_phone`(`phone` ASC) USING BTREE,
INDEX `idx_user_status`(`status` ASC) USING BTREE,
UNIQUE INDEX `uk_user_email`(`email` ASC) USING BTREE,
UNIQUE INDEX `uk_user_id_card`(`id_card` ASC) USING BTREE,
UNIQUE INDEX `uk_user_username`(`username` ASC) USING BTREE,
PRIMARY KEY (`id`)) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci AUTO_INCREMENT = 6 ROW_FORMAT = Dynamic COMMENT = '用户表';
-- 外键约束不指定约束名，由 MySQL 自动命名，避免与库内残留对象重名（错误 1826）
-- sys_button_auth Constraints
ALTER TABLE `sys_button_auth`
 ADD FOREIGN KEY (`route_id`) REFERENCES `sys_route_auth` (`id`) ON DELETE CASCADE ON UPDATE NO ACTION;
-- sys_role_button Constraints
ALTER TABLE `sys_role_button`
 ADD FOREIGN KEY (`button_id`) REFERENCES `sys_button_auth` (`button_id`) ON DELETE CASCADE ON UPDATE NO ACTION,
ADD FOREIGN KEY (`role_id`) REFERENCES `sys_role` (`role_id`) ON DELETE CASCADE ON UPDATE NO ACTION;
-- sys_role_route Constraints
ALTER TABLE `sys_role_route`
 ADD FOREIGN KEY (`role_id`) REFERENCES `sys_role` (`role_id`) ON DELETE CASCADE ON UPDATE NO ACTION,
ADD FOREIGN KEY (`route_id`) REFERENCES `sys_route_auth` (`id`) ON DELETE CASCADE ON UPDATE NO ACTION;
-- sys_route_auth Constraints
ALTER TABLE `sys_route_auth`
 ADD FOREIGN KEY (`parent_id`) REFERENCES `sys_route_auth` (`id`) ON DELETE CASCADE ON UPDATE NO ACTION;
-- sys_user_role Constraints
ALTER TABLE `sys_user_role`
 ADD FOREIGN KEY (`role_id`) REFERENCES `sys_role` (`role_id`) ON DELETE CASCADE ON UPDATE NO ACTION,
ADD FOREIGN KEY (`user_id`) REFERENCES `sys_user` (`id`) ON DELETE CASCADE ON UPDATE NO ACTION;
